export const SEO_PROGRAM = {}
for (const [id, seo] of Object.entries(PROGRAM_SEO)) {
  const g = id.startsWith('w') ? 'W' : 'M'
  SEO_PROGRAM[`${g}:${seo}`] = id
}

// Program id for a team on a game doc (needs gender because programs are per gender).
export const programIdForSeo = (gender, seo) => SEO_PROGRAM[`${gender}:${seo}`] || null

// Neutral fallback abbreviation from a display name: "Notre Dame" -> "ND", "Duke" -> "DUKE".
export function abbrFromName(name = '') {
  const words = String(name).replace(/[^A-Za-z&\s.]/g, '').split(/[\s.]+/).filter(Boolean)
  if (words.length === 0) return '?'
  if (words.length === 1) return words[0].slice(0, 4).toUpperCase()
  return words.map(w => w[0]).join('').slice(0, 4).toUpperCase()
}

// { abbr, bg, fg } for a team. bg/fg null = use the neutral token chip.
export function teamChipColors({ seo, programId, name } = {}) {
  const slug = seo || (programId && PROGRAM_SEO[programId])
  const hit = slug && TEAM_COLORS[slug]
  if (hit) return hit
  return { abbr: abbrFromName(name), bg: null, fg: null }
}
